window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["10"]={"https://www.gov.uk/foreign-travel-advice/botswana":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"5224f92d62ba4aadbaa1723b3c5e1f477654321c555cf665f961121ecab5ed09","read":"https://www.gov.uk/api/content/foreign-travel-advice/botswana","bytes":56188,"x":"fulltext v1","title":"Botswana travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-10T00:00:00+00:00","mod":"2026-11-06T14:39:38+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/botswana/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Botswana’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Botswana set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Botswana High Commission in the UK","https://www.gov.uk/government/publications/foreign-embassies-in-the-uk"],"."]},{"k":"p","s":["Telephone: 0207 499 0031"]},{"k":"p","s":["Email: bohico@govbw.com"]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Botswana, your passport must have an ‘expiry date’ at least 6 months after the date you arrive and at least 3 blank pages."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"p","s":["Make sure you get your passport stamped."]},{"k":"p","s":["This will record your date and port of entry. Unstamped passports will raise suspicions of illegal entry."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["Dual nationals must enter Botswana on the same passport they used to exit the previous country."]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Botswana for up to 90 days without a visa."]},{"k":"p","s":["If you want to work, study or volunteer in Botswana, see the ",["requirements for business, study and employment visas","https://www.gov.bw/immigration-civil-registration?txterm=114"],"."]},{"k":"p","s":["Overstaying a visa or a permitted visit can cause a delay to your departure. If you want to extend your stay, contact Botswana’s ",["Department of Immigration","https://www.gov.bw/contact-us"],"."]},{"k":"hs","s":["Travelling with children"]},{"k":"p","s":["You must carry the original or a certified copy of the full birth certificate for any child aged 17 or under entering or leaving Botswana."]},{"k":"p","s":["If a child is travelling with only one parent, with a guardian or another adult, or alone, carry the required parental consent or documents showing authority to travel. If parental consent is required, also carry a certified copy of the consenting parent’s passport or identity document."]},{"k":"p","s":["You can use GOV.UK guidance to ",["find a notary in the UK","https://www.gov.uk/guidance/find-a-notary-abroad"],". In Botswana, police stations can help with affidavits of consent. You can also use ",["Find a professional service abroad","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers"]," to find an English-speaking lawyer."]},{"k":"p","s":["For more information, contact the ",["Botswana High Commission in the UK","https://www.gov.uk/government/publications/foreign-embassies-in-the-uk"],"."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Botswana, you must have a certificate to prove you’ve had a yellow fever vaccination if you’re coming from a ",["country listed as a transmission risk","https://nathnacyfzone.org.uk/factsheet/65/countries-with-risk-of-yellow-fever-transmission"],"."]},{"k":"p","s":["For more details about health entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Botswana guide","https://travelhealthpro.org.uk/country/33/botswana#Vaccine_Recommendations"],"."]},{"k":"hs","s":["Ebola"]},{"k":"p","s":["As a public health measure, Botswana has introduced entry restrictions including health screening for travellers arriving from affected regions. ",["Check entry requirements","https://www.gov.uk/foreign-travel-advice"]," for the country you’re travelling to or transiting."]},{"k":"p","s":["The World Health Organisation (WHO) have ",["declared Ebola as a Public Health Emergency of International Concern","https://www.who.int/news/item/17-05-2026-epidemic-of-ebola-disease-in-the-democratic-republic-of-the-congo-and-uganda-determined-a-public-health-emergency-of-international-concern"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Botswana. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into Botswana"]},{"k":"p","s":["Declare foreign or local cash currency if the value is 10,000 Botswana pula or more. If you do not, you could be liable to prosecution."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Botswana"]},{"k":"p","s":["Although there’s no recent history of terrorism in Botswana, attacks cannot be ruled out."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Attacks on tourists are rare, but violent crime is increasing particularly in the major towns of Gaborone, Francistown and Maun. Criminals have also carried out hold-ups and robberies of restaurants during peak hours."]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Criminals may target cars waiting at traffic lights. To reduce the risk of attack:"]},{"k":"li","s":["keep doors locked and windows closed"]},{"k":"li","s":["keep handbags, phones and laptops out of sight"]},{"k":"li","s":["avoid carrying luggage in your vehicle whenever possible"]},{"k":"li","s":["do not stop for people at the roadside hitchhiking"]},{"k":"p","s":["House burglaries, often by armed gangs, are common. They do not often target tourists, but there have been isolated room break-ins and theft from lodges in the Chobe area, particularly river-fronting lodges. To reduce the risk of burglary or home invasion:"]},{"k":"li","s":["lock your room at all times"]},{"k":"li","s":["speak to your travel operator if your accommodation does not seem secure"]},{"k":"li","s":["secure valuables in a hotel safe or other safe place"]},{"k":"hs","s":["Sexual assault"]},{"k":"p","s":["Botswana has a high number of sexual assaults. While foreign visitors are unlikely to be targeted, women should take care when walking and avoid walking alone at night."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry some identification. A copy of the photo page in your passport is usually enough as long as you can produce the original if required."]},{"k":"p","s":["If you send your passport for renewal, make sure you have a certified copy that you can present in its place."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Drug taking and trafficking are illegal. If you’re convicted of a drug-related offence, you can get a fine of up to 500,000 pulas (about £30,000) or a prison sentence of up to 25 years, or both. Prison conditions are generally poor."]},{"k":"hs","s":["Using cameras in secure areas"]},{"k":"p","s":["It is illegal to take photographs or use video equipment near military and government installations. Always ask permission before photographing people in Botswana."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Although same-sex sexual activity is no longer prohibited by law, public attitudes are less tolerant than in the UK and displaying affection in public may attract negative attention."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Wildlife, animal products and souvenirs"]},{"k":"p","s":["It’s illegal to buy, sell, kill or capture any protected wild animal or trade its parts. If you’re caught hunting, buying or trafficking these goods you will be prosecuted. If you’re convicted, sentences can be severe."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"p","s":["If you travel to remote areas, make transport and accommodation arrangements in advance and seek local security advice. Take emergency supplies, including water and fuel, and be prepared for off-road driving conditions. In very remote areas, travel in convoy or with a satellite phone in case of breakdown."]},{"k":"p","s":["On open highways, inside or outside wildlife reserves, there could be dangerous animals roaming that may behave unpredictably. Always follow park regulations and advice from park wardens."]},{"k":"p","s":["Do not bathe in rivers and lakes. You could be attacked by wild animals and you risk catching water-borne diseases."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Botswana. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["1949 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well."]},{"k":"p","s":["You can drive with a UK driving licence for up to 90 days. If you intend to stay longer than 90 days, apply for a Botswana driving licence."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an IDP."]},{"k":"hs","s":["Driving conditions"]},{"k":"p","s":["Botswana has good tarmac roads covering most of the country, but driving outside the major urban areas can be dangerous due to stray wildlife and livestock. This is a particular risk at night, so take extra care if you’re driving after dark."]},{"k":"p","s":["The standard of driving is lower than in the UK. Many drivers ignore rules of the road. Speeding and drink-driving, or driving on drugs, cause frequent and often fatal accidents."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["To reduce risk of crime when using taxis, look for licensed taxis with blue plate numbers. Cabs run by a recognised taxi company will usually have branding and can be pre-booked."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Botswana’s rainy season, runs from November to March, bringing heavy rainfalls and risk of flash flooding. Road conditions throughout the country may be unsafe. Follow the advice of ",["Botswana’s Meteorological Services","https://www.facebook.com/BotswanaMet"]," and from the local authorities at ",["Ministry of Environment and Tourism","https://www.facebook.com/people/Ministry-of-Environment-and-Tourism-Botswana/61569658071888/"],"."]},{"k":"p","s":["Floodings may also impact border crossings with closure at short notice. Follow the advice of ",["Botswana’s Unified Revenue Services","https://www.facebook.com/BotswanaUnifiedRevenueService"]," for latest updates on road accessibility and border opening and closure status."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 997 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Botswana","https://travelhealthpro.org.uk/country/33/botswana#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Botswana","https://travelhealthpro.org.uk/country/33/botswana"]," including:"]},{"k":"li","s":["malaria, which is reported in April 2025 to have spread to areas where it is not usually present"]},{"k":"li","s":["schistosomiasis"]},{"k":"p","s":["There are occasional outbreaks of anthrax among wild animals. Do not touch dead animals or carcases. If you suspect that you have come into contact with anthrax, seek urgent medical advice."]},{"k":"p","s":["If you intend to camp or walk in the bush, take precautions to avoid tick bites, as they can cause several dangerous diseases."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Botswana"]},{"k":"p","s":["The State of Public Health Emergency is now over. Despite this, medicine and medical supply shortages remain widespread across public health facilities nationwide. Private healthcare remains largely unaffected."]},{"k":"p","s":["Healthcare in Botswana is usually good in major towns, but medical facilities and communications are limited in rural areas. For serious medical treatment, medical evacuation to the UK or South Africa may be necessary."]},{"k":"p","s":["Private hospitals will not treat you unless you can pay, and the cost may be high. Public hospitals will only take you as an emergency patient if you have full insurance. For outpatient treatment, you will need to pay up front."]},{"k":"p","s":["Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Botswana","https://www.gov.uk/government/publications/botswana-list-of-medical-facilities/botswana-list-of-medical-facilities"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Botswana"]},{"k":"p","s":["Ambulance: 997"]},{"k":"p","s":["Fire: 998"]},{"k":"p","s":["Police: 999"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding ",["lawyers in Botswana","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Botswana"]]},{"k":"li","s":["dealing with a ",["death in Botswana","https://www.gov.uk/guidance/what-to-do-after-a-british-person-dies-in-botswana"]]},{"k":"li","s":["being ",["arrested or imprisoned in Botswana","https://www.gov.uk/government/publications/botswana-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/botswana/british-high-commission-gaborone"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/botswana/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":13535,"change":"Updated information about the documents needed when travelling with children (see 'Travelling with children' on the 'Entry requirements' page)."},"https://www.gov.uk/foreign-travel-advice/western-sahara":{"r":"govuk","at":"2026-11-17T16:38Z","sha":"d696847051e8c34b871e651ed6b2942034c9958238edcb69e65943ab4bbf1301","read":"https://www.gov.uk/api/content/foreign-travel-advice/western-sahara","bytes":38139,"x":"fulltext v1","title":"Western Sahara travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-05T00:00:00+00:00","mod":"2026-06-29T14:34:01+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against all travel"]},{"k":"p","s":["FCDO advises against all travel to:"]},{"k":"li","s":["Areas in Western Sahara within 40km North and West of ‘the Berm’ boundary line, including the city of Es Semara"]},{"k":"li","s":["Areas in Western Sahara the territory south and east of ‘the Berm’ boundary line"]},{"k":"p","s":["Western Sahara is a disputed territory. The Berm is the militarised boundary between Moroccan-controlled Western Sahara and territory to the east controlled by the Polisario Front. Cross border rocket fire has occurred which cannot be ruled out in the future."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/western-sahara/regional-risks"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/western-sahara/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Western Sahara’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Western Sahara set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Moroccan Consulate General in the UK","https://www.consulat.ma/en"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Your passport must be valid for the proposed duration of your stay."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can travel without a visa for visits to the Moroccan-administered parts of Western Sahara and Morocco for up to 90 days."]},{"k":"p","s":["Travel is restricted. Organised groups are generally permitted, but independent travellers could be turned back at the border."]},{"k":"p","s":["Make sure you get your passport stamped."]},{"k":"p","s":["When first arriving in Morocco/Western Sahara, make sure you get a passport stamp from the Moroccan border control authorities. You may have difficulty leaving the country without a stamp."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Western Sahara guide","https://travelhealthpro.org.uk/country/245/western-sahara#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Western Sahara. You must declare anything that may be prohibited or subject to tax or duty. Check ",["Moroccan customs rules","https://www.douane.gov.ma/web/guest/particuliers"]," (in French) for the Moroccan-administered parts of Western Sahara."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Western Sahara"]},{"k":"p","s":["Terrorists are likely to try to carry out attacks in Western Sahara."]},{"k":"p","s":["Attacks could be indiscriminate, including in places visited by foreign nationals. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Western Sahara is on the UN list of Non-Self-Governing Territories and the subject of a UN-mediated dispute. The UN Peacekeeping mission for Western Sahara, MINURSO, has been operating in the country since 1991. A ceasefire between Morocco and the Polisario Front broke down in 2020. Irregular skirmishes continue to take place between the 2 sides, sometimes resulting in civilian casualties."]},{"k":"p","s":["Most of Western Sahara is under administration of Morocco, which closely monitors and controls access to the territory. You should avoid political gatherings and demonstrations."]},{"k":"p","s":["Follow any media reporting and instructions from local security authorities."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"p","s":["Western Sahara is predominantly Muslim. Always respect local traditions, customs, laws and religion. Make sure your actions do not offend, especially during the holy month of Ramadan or if you plan to visit religious areas."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan is a holy month for Muslims. The dates vary by year and country, so check when Ramadan is in Western Sahara before you go. During this time, do not:"]},{"k":"li","s":["eat, drink, smoke or chew gum in public in the daytime, including in your car"]},{"k":"li","s":["play loud music or dance"]},{"k":"li","s":["swear in public"]},{"k":"p","s":["Get more advice when you arrive from your tour guide, hotel or business contacts."]},{"k":"p","s":["You should also:"]},{"k":"li","s":["check opening hours of shops and restaurants"]},{"k":"li","s":["be aware that if hotels and restaurants are providing food or drink in fasting hours, they may separate you from Islamic guests, for example with screens"]},{"k":"li","s":["follow local dress codes – clothing that doesn’t meet local dress codes may cause more offence at this time"]},{"k":"li","s":["be aware that driving may be erratic, particularly when people are trying to get home at dusk"]},{"k":"hs","s":["Laws against religious conversion"]},{"k":"p","s":["It is illegal to attempt to convert any Muslim to another faith or to distribute evangelical literature, such as Arabic-language bibles. Attempting to convert a Muslim to another faith is punishable by fines or up to 3 years in prison."]},{"k":"p","s":["Criticism of Islam on public platforms, in print or online media, or in public speeches is punishable by heavy fines and up to 2 years in prison."]},{"k":"hs","s":["Sexual relations outside of marriage"]},{"k":"p","s":["Sexual activity between unmarried people and adultery are illegal – this includes sharing a hotel room."]},{"k":"p","s":["The law against unmarried people sharing a hotel room does not generally apply to visiting foreign nationals, particularly in popular tourist areas."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is illegal. Be sensitive to local laws and customs and avoid showing affection in public. Complaints can lead to prosecution."]},{"k":"p","s":["See more ",["advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Women travellers"]},{"k":"p","s":["Women may receive unwanted attention from men, especially when travelling alone. Consider wearing loose-fitting clothing which cover the arms, legs and chest. See ",["advice for women travelling abroad","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"],"."]},{"k":"hs","s":["Alcohol laws"]},{"k":"p","s":["Licensed hotels, restaurants and bars serve alcohol in tourist areas. Drinking alcohol in the street or anywhere other than licensed premises is illegal and can lead to arrest."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Western Sahara, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You’ll need to have both the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["If you are staying in Western Sahara for longer than one year, you must apply for a ",["Moroccan driving licence","https://consulat.ma/en/driving-license"],"."]},{"k":"p","s":["If you’re planning to hire a car, check with your car hire company for information on their requirements before you travel."]},{"k":"p","s":["Drive carefully, especially when:"]},{"k":"li","s":["driving at night, which be particularly dangerous due to poor lighting"]},{"k":"li","s":["weather conditions are poor on secondary routes and mountain roads"]},{"k":"li","s":["overtaking lorries and trucks that are overloaded and when there is no hard shoulder"]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Western Sahara. It only covers regions where the Foreign, Commonwealth & Development Office (FCDO) has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/western-sahara"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/western-sahara/safety-and-security"],"."]},{"k":"h","s":["Landmines, unexploded weapons and rocket fire"]},{"k":"p","s":["A militarised boundary known as ‘the Berm’ separates the Moroccan-administered part of Western Sahara from the rest of the territory. There are 30km militarised zones either side of the Berm containing landmines. There have been many fatalities in these zones. Cross border rocket fire has occurred which cannot be ruled out in the future."]},{"k":"p","s":["FCDO advises against all travel to:"]},{"k":"li","s":["Areas in Western Sahara within 40km North and West of ‘the Berm’ boundary line, including the city of Es Semara"]},{"k":"li","s":["Areas in Western Sahara the territory south and east of ‘the Berm’ boundary line"]},{"k":"p","s":["The eastern side of the Berm is sparsely populated with no diplomatic presence from any country. There are other types of unexploded weapons in this area."]},{"k":"p","s":["In remote areas:"]},{"k":"li","s":["keep to main roads and stay alert"]},{"k":"li","s":["if you drive off the main roads, keep to clearly identifiable tracks"]},{"k":"li","s":["do not touch any metal or plastic objects"]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 150 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Western Sahara","https://www.travelhealthpro.org.uk/country/245/western-sahara#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Western Sahara","https://travelhealthpro.org.uk/country/245/western-sahara"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Western Sahara"]},{"k":"p","s":["Medical facilities are adequate in the main cities – Laayoune, Dhakla and Smara – all of which have hospitals, clinics and pharmacies. For more sophisticated medical treatment, including scans, you will need to go to a major centre in Morocco or the Canary Islands."]},{"k":"p","s":["Medical facilities are almost non-existent in desert areas. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Western Sahara"]},{"k":"p","s":["Telephone: 150 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/western-sahara/british-embassy-rabat"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/western-sahara/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":12242,"change":"FCDO now advises against all travel to areas in Western Sahara within 40km North and West of 'the Berm' boundary line, including the city of Es Semara ('Warnings and insurance' page)."},"https://theconversation.com/mengapa-pemimpin-otoriter-dan-antikritik-kerap-banyak-pemujanya-294906":{"r":"conversation","at":"2026-11-17T16:47Z","sha":"1ff7883300749e2bee843795011ea4a8bc17ede79328aaf05927ffe7ba29a0dc","read":"https://theconversation.com/mengapa-pemimpin-otoriter-dan-antikritik-kerap-banyak-pemujanya-294906","bytes":178824,"x":"fulltext v1","title":"Mengapa pemimpin otoriter dan antikritik kerap banyak pemujanya?","by":[{"n":"Nayunda Andhika Sari","r":"Lecturer in Management and Organisation Studies, Universitas Indonesia"},{"n":"Kanti Pertiwi","r":"Assistant Professor in Organisation Studies, Universitas Indonesia"}],"pub":"2026-11-13T02:16:50Z","mod":"","blocks":[{"k":"p","s":["• Pemimpin dominan kerap dianggap kompeten, tapi bisa membungkam kritik dan perbedaan pendapat."]},{"k":"p","s":["• Budaya organisasi dan masyarakat ikut melanggengkan kepemimpinan heroik dan antikritik."]},{"k":"p","s":["• Kepemimpinan perlu mengutamakan kolaborasi dan memberi ruang bagi semua orang untuk bersuara."]},{"k":"p","s":["Pemimpin yang membentak bawahan di depan umum kerap dipandang tegas oleh sebagian kalangan. Begitu pula pejabat yang mengambil keputusan sepihak masih sering dianggap berani. Sementara itu, pemimpin yang mengakui kesalahan atau meminta masukan justru berisiko dicap lemah."]},{"k":"p","s":["Pandangan ini menunjukkan betapa kuatnya anggapan bahwa ",["pemimpin ideal","https://www.sciencedirect.com/science/article/abs/pii/1048984394900051"]," harus dominan, berkarisma, dan selalu memiliki jawaban atas setiap persoalan."]},{"k":"p","s":["Masalahnya, ketegasan sering disamakan dengan kemampuan memimpin, sementara kepatuhan dianggap sebagai bukti keberhasilan kepemimpinan. Akibatnya, perilaku otoriter bisa memperoleh dukungan, sekalipun itu bisa merugikan organisasi dan masyarakat."]},{"k":"p","s":["Mengapa pola ini terus bertahan? Duduk permasalahan ini bukan semata berasal dari karakter pemimpin, tetapi juga pengaruh budaya yang membentuk, memuja, dan mempertahankan tradisi ini."]},{"k":"h","s":["Dominasi dianggap kompetensi"]},{"k":"p","s":["Dalam kajian kepemimpinan, kecenderungan menempatkan pemimpin sebagai sosok luar biasa yang menentukan keberhasilan organisasi dikenal sebagai ",["heroic leadership (kepemimpinan heroik)","https://www.tandfonline.com/doi/abs/10.1080/00220620.2010.492959"],"."]},{"k":"p","s":["Perspektif ini menganggap keberhasilan terutama berasal dari keberanian, kecerdasan, dan keputusan seorang pemimpin. Kontribusi pekerja, kondisi organisasi, serta faktor sosial dan politik kerap terabaikan."]},{"k":"p","s":[["https://www.facebook.com/reel/1557882292118422","https://www.facebook.com/reel/1557882292118422"]]},{"k":"p","s":[["Penelitian tentang kategorisasi kepemimpinan","https://www.sciencedirect.com/science/article/abs/pii/0030507384900436?"]," menunjukkan bahwa manusia memiliki gambaran tertentu tentang karakter pemimpin ideal. Gambaran tersebut memengaruhi siapa yang dianggap layak memimpin."]},{"k":"p","s":["Ketika dominasi diagungkan, orang yang berbicara paling keras atau tampil paling percaya diri lebih mudah dianggap kompeten. Padahal belum tentu."]},{"k":"p","s":["Dalam masyarakat dengan hierarki kekuasaan yang kuat, kecenderungan ini berpotensi semakin mengakar."]},{"k":"p","s":["Kita bisa melihatnya dalam keseharian. Di kantor, atasan yang mendominasi rapat dianggap berwibawa. Sementara bawahan yang mempertanyakan keputusan dicap tidak loyal."]},{"k":"p","s":["Di ruang publik, video pejabat memarahi staf bisa memperoleh pujian karena dianggap menunjukkan ketegasan."]},{"k":"p","s":["Padahal, kemampuan mempermalukan bawahan bukan ukuran kompetensi, apalagi keberhasilan kebijakan."]},{"k":"p","s":["Masalah semakin serius ketika organisasi ikut mempertahankan pola tersebut. Bawahan memilih diam demi menjaga karier atau menjilat pemimpin karena yakin posisinya tak tergoyahkan."]},{"k":"p","s":["Fenomena ini berkaitan dengan employee silence, yakni kecenderungan pekerja menahan informasi, kekhawatiran, atau kritik terhadap organisasi. ",["Riset tentang psikologi organisasi","https://www.annualreviews.org/content/journals/10.1146/annurev-orgpsych-031413-091328"]," menjelaskan bahwa ketakutan terhadap konsekuensi negatif menjadi salah satu alasan pekerja enggan bersuara."]},{"k":"p","s":["Nyatanya pemimpin antikritik tidak selalu bertahan karena dianggap berhasil. Mereka juga bisa terus memperoleh legitimasi karena lingkungan membuat kritik terasa berisiko."]},{"k":"h","s":["Kepemimpinan bukan pertunjukan satu orang"]},{"k":"p","s":["Dominasi pemimpin semakin mudah dipasarkan melalui media sosial."]},{"k":"p","s":[["Konten pejabat","https://theconversation.com/viral-dulu-substansi-belakangan-3-risiko-punya-pemimpin-politik-kreator-konten-259378"]," yang melakukan inspeksi mendadak, memarahi bawahan, atau menunjukkan aksi simbolis dapat membangun citra sebagai penyelamat. Namun, popularitas tindakan tersebut tidak otomatis membuktikan efektivitas kebijakan."]},{"k":"p","s":["Ketika perhatian hanya tertuju pada figur, pangkal persoalan utama sering luput dari perhatian: apakah persoalan terselesaikan? kebijakannya berdampak? dan siapa yang menanggung akibat keputusan tersebut?"]},{"k":"p","s":["Di sinilah pentingnya perspektif ",["post-heroic leadership","https://www.amazon.com/Shared-Leadership-Reframing-Hows-Whys/dp/0761926240/ref=mt_paperback?_encoding=UTF8&me="],". Berbeda dengan kepemimpinan heroik, pendekatan ini melihat kepemimpinan sebagai ",["proses kolektif","https://www.amazon.com/Shared-Leadership-Reframing-Hows-Whys/dp/0761926240/ref=mt_paperback?_encoding=UTF8&me="]," yang melibatkan hubungan, kerja sama, dan pembagian pengaruh, bukan kehebatan satu individu."]},{"k":"p","s":[["Kajian Fletcher","https://www.sciencedirect.com/science/article/pii/S1048984304000827"]," menekankan pentingnya praktik kepemimpinan yang lebih relasional dan tidak bergantung pada figur tunggal. Artinya, pemimpin tetap memiliki tanggung jawab mengambil keputusan, tetapi tidak memonopoli pengetahuan dan kewenangan."]},{"k":"p","s":["Dalam penanganan krisis, misalnya, pemimpin yang efektif bukan yang paling lantang menyalahkan bawahan atau ",["“asbun” (asal bunyi)","https://theconversation.com/pejabat-bukan-gen-alpha-asbun-mereka-saat-asap-karhutla-bukan-salah-ucap-tapi-krisis-empati-294869"],", tetapi yang mendengarkan ahli, menerima laporan lapangan, mengakui kesalahan, dan memperbaiki kebijakan berdasarkan bukti."]},{"k":"p","s":["Pendekatan ini juga penting bagi organisasi. ",["Penelitian Edmondson (1999)","https://journals.sagepub.com/doi/10.2307/2666999"]," menunjukkan bahwa psychological safety, yakni rasa aman untuk mengambil risiko interpersonal, berkaitan dengan perilaku belajar dalam tim."]},{"k":"p","s":["Dengan kata lain, ruang untuk bertanya, berbeda pendapat, dan mengakui kesalahan bukan ancaman bagi kepemimpinan, melainkan bagian penting dari organisasi yang mampu belajar."]},{"k":"h","s":["Berhenti memuja jabatan, mulai memperkuat kritik"]},{"k":"p","s":["Mengubah budaya kepemimpinan tidak cukup dengan meminta pejabat lebih rendah hati. Kita pun perlu ",["mengurangi pendewaan dan penghormatan kepada kekuasaan","https://books.google.com.bh/books?hl=en&lr=&id=ZXX3CgAAQBAJ&oi=fnd&pg=PT7&dq=The+Stupidity+Paradox&ots=t-SOtvdUaf&sig=cLddZvqCAk1opljJPNEm8xg4tQc&redir_esc=y#v=onepage&q&f=false"],"."]},{"k":"p","s":["Di lingkungan kerja, misalnya, rapat seharusnya memberi ruang bagi pekerja untuk menyampaikan pandangan berbeda tanpa takut mendapat penilaian buruk. Sebisa mungkin kurangi bahasa sehari-hari yang menguatkan hierarki seperti ",["siap dan mohon izin","https://www.thejakartapost.com/indonesia/2026/07/06/izin-and-siap-military-lingo-creeps-into-civilian-life"]," guna mencegah pendewaan pada figur."]},{"k":"p","s":["Di ruang publik, masyarakat perlu berhenti menjadikan kemarahan pejabat, seremoni berlebihan, atau kedekatan dengan penguasa sebagai ukuran kepemimpinan. Misalnya, kurangi seremonial penyambutan pemimpin yang berlebihan, foto bareng dan cium tangan pejabat, dan ",["mulailah berani untuk mengkritisi kebijakan mereka di forum-forum terbuka","https://www.youtube.com/watch?v=gW00hnnVNf4"]]},{"k":"p","s":["Dunia akademik juga memiliki tanggung jawab. Pendidikan dan perkuliahan seputar kepemimpinan perlu mengurangi narasi tentang ",["pemimpin sebagai pahlawan tunggal","https://journals.aom.org/doi/abs/10.5465/amle.2014.0079"]," dan lebih banyak membahas kontribusi pekerja, relasi kekuasaan, kondisi sosial yang memengaruhi keberhasilan organisasi hingga ",["dampaknya untuk masyarakat di mana organisasi itu berada","https://journals.aom.org/doi/abs/10.5465/amle.2019.0289"],"."]},{"k":"p","s":[["Post-heroic leadership","https://www.sciencedirect.com/science/article/pii/S1048984304000827"]," bukan berarti meniadakan pemimpin. Pendekatan ini menolak anggapan bahwa kekuasaan harus terkonsentrasi pada satu figur yang selalu benar."]},{"k":"p","s":["Kepemimpinan yang sehat bukan ditandai oleh banyaknya orang yang patuh dan bertepuk tangan, melainkan oleh ",["keberanian mereka","https://www.annualreviews.org/content/journals/10.1146/annurev-orgpsych-031413-091328"]," untuk berbeda pendapat tanpa takut kehilangan suara."]}],"chars":6192},"https://theconversation.com/ketidakbecusan-pemerintah-dalam-mengurus-bencana-memengaruhi-narasi-kemerdekaan-di-aceh-292896":{"r":"conversation","at":"2026-11-17T16:47Z","sha":"6cbdc45b0a02f51983425d7f926a5a6c833fd8626875e48c6867e823770e70da","read":"https://theconversation.com/ketidakbecusan-pemerintah-dalam-mengurus-bencana-memengaruhi-narasi-kemerdekaan-di-aceh-292896","bytes":189599,"x":"fulltext v1","title":"Ketidakbecusan pemerintah dalam mengurus bencana memengaruhi narasi kemerdekaan di Aceh","by":[{"n":"Azifah Astrina","r":"Ph.D. candidate in Political Science, University of Illinois Urbana-Champaign; Universitas Gadjah Mada"}],"pub":"2026-10-01T06:33:14Z","mod":"","blocks":[{"k":"p","s":["Ribuan orang berkumpul di Masjid Raya Baiturrahman Banda Aceh pada ",["15 Agustus 2026","https://en.tempo.co/read/2117590/aceh-peace-day-tribute-turns-violent-as-crowd-clashes-with-police"]," untuk memperingati ",["21 tahun","https://theacehpost.com/news/bendera-merah-putih-di-pendopo-gubernur-aceh-diturunkan-massa-berkibar-bulan-bintang/index.html"]," perdamaian antara Indonesia dan Gerakan Aceh Merdeka (GAM)."]},{"k":"p","s":["Beberapa peserta mengibarkan bendera bulan bintang berwarna merah, hitam, dan putih sembari meneriakkan “Aceh merdeka.” Sementara peserta lainnya menurunkan bendera merah putih dan menggantinya dengan bendera Aceh."]},{"k":"p","s":["Tindakan ini signifikan secara politik di provinsi tempat konflik bersenjata yang mengupayakan kemerdekaan berlangsung selama hampir ",["tiga dekade","https://media.defense.gov/2025/Apr/07/2003683780/-1/-1/0/20250407_INDONESIA_ACEH_1976-2005%20_FINAL.PDF"]," —sebelum Perjanjian Helsinki 2005 mengakhirinya."]},{"k":"p","s":["Aksi 15 Agustus tersebut bukanlah insiden tunggal. Dalam ulang tahun GAM pada ",["Desember 2024","https://www.thejakartapost.com/indonesia/2024/12/05/gams-crescent-and-star-flag-raised-in-lhoukseumawe"],", mantan anggota GAM juga mengibarkan bendera serupa. Seorang eks kombatan menyuarakan harapan agar bendera itu akhirnya dapat berkibar di seluruh Aceh."]},{"k":"p","s":["Bendera tersebut kemudian meramaikan jalan-jalan di Aceh pada ",["Desember 2025","https://en.tempo.co/read/2076220/tni-disperses-crowds-flying-gam-flags-in-acehs-lhokseumawe"]," sebelum prajurit TNI membubarkan kerumunan yang mengibarkannya."]},{"k":"p","s":["Kembalinya simbol dan slogan ini terjadi saat Aceh berusaha pulih dari banjir parah dan tanah longsor pada akhir ",["November 2025","https://www.pbs.org/newshour/world/death-toll-rises-to-164-after-floods-and-landslides-on-indonesias-sumatra-island"],". Padahal, bencana alam yang berbeda, yaitu Tsunami 2004, ",["justru menciptakan kondisi","https://doi.org/10.1016/j.geoforum.2007.10.010"]," yang mempercepat proses perdamaian antara Aceh dan Jakarta."]},{"k":"p","s":["Dua dekade kemudian, ",["kritik","https://news.mongabay.com/2026/06/survivors-sue-indonesian-government-over-response-to-catastrophic-sumatra-floods/"]," terhadap respons pemerintah pusat terhadap penanganan bencana justru memperkuat ekspresi warga Aceh."]},{"k":"p","s":["Sebagai seorang ",["akademisi nasionalisme dan geografi politik","https://pol.illinois.edu/directory/profile/astrina2"],", saya melihat kebangkitan sentimen prokemerdekaan di Aceh bukan sekadar bukti bahwa separatisme sedang kembali."]},{"k":"p","s":["Ia merupakan pengingat bahwa nasionalisme terus-menerus dinegosiasikan antara negara dengan warganya, serta dapat dirusak oleh pengabaian di saat-saat membutuhkan."]},{"k":"p","s":["Kesepakatan perdamaian di Aceh yang mengubah konflik separatis berdarah menjadi salah satu contoh ",["rekonsiliasi","https://globalsouthforum.org/article/aceh-at-the-crossroads-hope-for-peace-and-political-challenges-in-a-new-era"]," terbaik di Asia Tenggara. Ketegangan saat ini tidak hanya menimbulkan pertanyaan tentang hubungan Aceh dengan Indonesia, tetapi juga daya tahan perdamaian yang berlangsung lebih dari dua dekade."]},{"k":"h","s":["Perdamaian mengakhiri perang, bukan nasionalisme"]},{"k":"p","s":["Perjuangan GAM sebenarnya melampaui penolakan mereka terhadap kebijakan-kebijakan yang dibuat di Jakarta. Berdiri pada 1976, gerakan ini menampilkan Aceh sebagai bangsa terpisah yang harus merdeka dari Indonesia."]},{"k":"p","s":["GAM mengandalkan sejarah Aceh untuk menggambarkan kemerdekaan ",["sebagai pemulihan","https://onlinelibrary.wiley.com/doi/abs/10.1111/j.1469-8129.2007.00277.x"]," dari kedaulatan ketika Aceh masih menjadi kesultanan independen."]},{"k":"p","s":["Konflik GAM - Indonesia yang berlangsung hampir tiga dekade tersebut ",["menewaskan ribuan orang","https://reliefweb.int/report/indonesia/no-peace-without-justice-victims-indonesia%E2%80%99s-aceh-conflict-demand-truth-justice-and"],". Warga sipil menanggung sebagian besar kekerasan, dengan aparat Indonesia dan GAM sama-sama ",["terlibat dalam pelanggaran","https://www.hrw.org/news/2005/05/27/acehs-forgotten-victims"],". Ini termasuk penyiksaan, penangkapan sewenang-wenang, pemerasan, dan pengungsian paksa."]},{"k":"p","s":["Pada 2004, tsunami dahsyat ",["bertindak sebagai katalis perdamaian","https://doi.org/10.1016/j.geoforum.2007.10.010"],", menyoroti penderitaan populasi Aceh sekaligus membuka pintu bagi bantuan dan kehadiran internasional."]},{"k":"p","s":["Konflik bersenjata secara resmi berakhir dengan penandatanganan ",["Perjanjian Helsinki 2005","https://peacemaker.un.org/sites/default/files/document/files/2024/05/id050815memorandum20of20understanding.pdf"],", tetapi itu tidak membuat nasionalisme Aceh lenyap."]},{"k":"p","s":["Sebaliknya, perdamaian mengakomodasi kekhasan politik Aceh. Perdamaian membuat Aceh memiliki kewenangan pemerintahan sendiri yang luas, mengizinkan partai politik lokal, memperluas representasi politik, dan memberikan daerah tersebut wewenang untuk mengesahkan undang-undang tingkat provinsi."]},{"k":"p","s":["Keleluasaan atas urusan ekonomi dan sumber daya alam diserahkan kepada Aceh, meskipun keluhan yang tersisa mengenai ",["ketentuan bagi hasil terkait ladang gas di sana","https://www.jstor.org/stable/27638587"]," tetap ada hingga hari ini."]},{"k":"p","s":["Penyelesaian politik tersebut sebagian besar berhasil mengakhiri konflik bersenjata. GAM memang melucuti senjatanya. Banyak pula mantan pemimpinnya yang ",["beralih ke","https://journals.sagepub.com/doi/10.1177/186810341002900105"]," politik pemilu, membentuk partai-partai lokal dan memenangkan posisi-posisi di pemerintahan serta DPR Aceh. Namun, gagasan dan simbol-simbol pro-kemerdekaan tidak sepenuhnya hilang."]},{"k":"p","s":["Pembedaan itu penting karena perdamaian tidak bergantung pada orang Aceh yang meninggalkan identitas politik khas mereka dan menjadi orang Indonesia. Itu bergantung pada pengubahan syarat-syarat hubungan mereka dengan Indonesia."]},{"k":"p","s":["Aceh dapat tetap menjadi bagian dari negara ini sambil mempertahankan kontrol yang besar atas urusan politiknya sendiri. Dalam pengertian itu, Helsinki bukan hanya mengakhiri perang, tetapi juga menciptakan kondisi politik yang membuat Aceh tak berpisah dari Indonesia."]},{"k":"h","s":["Dari bencana menuju pembicaraan kemerdekaan"]},{"k":"p","s":["Banjir dan tanah longsor pada November 2025 menewaskan ",["lebih dari seribu orang","https://thediplomat.com/2025/12/acehs-bitter-lesson-relearned/"]," dan mengakibatkan lebih dari sejuta pengungsi."]},{"k":"p","s":["Aceh termasuk di antara provinsi yang terdampak paling parah, sehingga penduduknya lebih bergantung pada otoritas publik untuk bantuan tanggap darurat dan pemulihan."]},{"k":"p","s":["Desakan agar Presiden menetapkan banjir dan tanah longsor tersebut sebagai ",["bencana nasional","https://www.kompas.id/artikel/en-desakan-penetapan-bencana-nasional-di-sumatera-terus-mengalir-dari-aceh"]," dimulai tak lama setelah bencana menerjang. Namun, Presiden Prabowo Subianto menolaknya karena merasa Indonesia masih mampu."]},{"k":"p","s":["Penolakan Prabowo terhadap bantuan luar negeri menyebabkan ",["kemarahan meluas di Aceh","https://www.bbc.com/news/articles/ckgzwqjpzp4o"]," —berbanding terbalik dengan respons Tsunami 2004, ketika bantuan internasional sangat krusial bagi upaya pascabencana."]},{"k":"p","s":["Hampir setahun kemudian, Aceh masih jauh dari pulih. Per 7 September 2026, hanya ",["649 dari 34.777 rumah permanen","https://www.antaranews.com/berita/5730356/satgas-prr-catat-649-unit-hunian-tetap-di-aceh-telah-rampung"]," yang terbangun."]},{"k":"p","s":["Data terbaru yang tersedia juga menunjukkan bahwa 93 ruas jalan daerah masih belum dapat berfungsi. Sementara hanya 188 dari 676 jembatan yang telah dipulihkan per ",["8 Agustus","https://dialeksis.com/aceh/sembilan-bulan-pascabencana-warga-aceh-masih-menunggu-rumah-dan-akses-permanen/"],"."]},{"k":"p","s":["Pada ",["14 Agustus,","https://en.tempo.co/read/2117590/aceh-peace-day-tribute-turns-violent-as-crowd-clashes-with-police"]," sehari sebelum acara bendera GAM, koalisi masyarakat sipil kembali mengibarkan bendera putih dan mendesak Jakarta untuk menyatakan bencana tersebut sebagai bencana nasional."]},{"k":"p","s":["Namun mengapa keluhan atas respons pemerintah berubah menjadi pembicaraan prokemerdekaan di Aceh? Sejarah memberikan sebagian jawabannya."]},{"k":"p","s":["Kuatnya identitas Aceh tidak selalu berujung pada aspirasi kemerdekaan. ",["Pemimpin-pemimpin Aceh","https://doi.org/10.1111/j.1469-8129.2007.00277.x"]," yang mendukung kemerdekaan Indonesia dari Belanda pada tahun 1945, dan bahkan ",["pemberontakan Darul Islam","https://media.defense.gov/2024/Mar/20/2003416575/-1/-1/0/20240306_DARULISLAM_1949-62.PDF"]," pada tahun 1950-an, tidak berusaha membentuk negara Aceh yang independen."]},{"k":"p","s":["Sebaliknya, penolakan terhadap pemerintahan kolonial Belanda, yang diikuti oleh jaringan dan solidaritas Islam, ",["justru menghubungkan","https://doi.org/10.1111/j.1469-8129.2007.00277.x"]," elite Aceh dengan komunitas politik Indonesia yang lebih luas."]},{"k":"p","s":["Baru belakangan, ketika hubungan dengan pemerintah pusat memburuk, kemerdekaan menjadi tujuannya."]},{"k":"p","s":["Sejarah ini menunjukkan bahwa nasionalisme Aceh bukanlah kekuatan politik kaku yang secara berkala muncul kembali tanpa perubahan. Pemahaman yang berbeda mengenai bangsa dapat ",["bersaing dan dinegosiasikan ulang","https://doi.org/10.1111/j.1469-8129.2007.00277.x"]," seiring berubahnya kondisi politik."]},{"k":"p","s":["Oleh karena itu, identitas nasional Aceh dan Indonesia tidak selalu saling meniadakan; hubungan keduanya telah berubah seiring berubahnya hubungan politik antara Aceh dan Jakarta."]},{"k":"p","s":["Kembalinya seruan “Aceh Merdeka” dan simbol-simbol terkait GAM menunjukkan bahwa, 21 tahun setelah kesepakatan perdamaian, kemerdekaan menjadi bahasa politik untuk mengekspresikan ketidakpuasan terhadap Indonesia. Ini terutama di momen krusial seperti penanganan bencana yang tak beres sehingga merusak ",["legitimasi pemerintah","https://doi.org/10.1111%2Fgove.12440"],"."]},{"k":"h","s":["Nasionalisme sebagai proses dua arah"]},{"k":"p","s":["Selama lebih dari dua dekade, Aceh tetap damai dan berada di dalam Indonesia, sambil mempertahankan otonomi yang luas dan identitas politik yang khas."]},{"k":"p","s":["Namun, penggunaan slogan “Aceh Merdeka” dan simbol-simbol separatis menunjukkan bahwa rasa memiliki terhadap Indonesia tidak secara sederhana tuntas oleh perdamaian, otonomi, atau berlalunya waktu."]},{"k":"p","s":["Nasionalisme juga tidak dapat dipahami secara sederhana hanya dengan melihat bagaimana negara-negara membangun identitas melalui ",["sekolah, peta, bendera, dan upacara","https://onlinelibrary.wiley.com/doi/epdf/10.1111/nana.70002"],"."]},{"k":"p","s":["Nasionalisme bekerja dua arah: Indonesia mempromosikan identitas bersama, tetapi orang Aceh juga mencerna apa arti menjadi warga Indonesia melalui interaksi dengan negara."]},{"k":"p","s":["Mungkin pertanyaan yang lebih penting, bukanlah mengapa pembicaraan kemerdekaan kembali muncul, melainkan apa yang telah menjaga Aceh tetap berada di dalam Indonesia selama 21 tahun terakhir."]}],"chars":7932}};
